const GACHA_EN = JSON.parse("[{\"id\":\"no-worries\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"No worries\",\"m\":\"괜찮아, 걱정 마\",\"lit\":\"\",\"ex\":\"No worries, I can wait.\",\"exko\":\"괜찮아, 기다릴 수 있어.\",\"tip\":\"고맙다·미안하다는 말에 '괜찮아~' 하고 가볍게 답할 때. 호주 사람들의 입버릇이에요.\"},{\"id\":\"my-bad\",\"r\":\"N\",\"cat\":\"슬랭\",\"w\":\"My bad\",\"m\":\"내 실수, 미안\",\"lit\":\"\",\"ex\":\"Oops, my bad! I took your seat.\",\"exko\":\"앗, 내 실수! 네 자리에 앉았네.\",\"tip\":\"I'm sorry보다 훨씬 가벼운 사과. 친구 사이에서만 써요.\"},{\"id\":\"im-down\",\"r\":\"N\",\"cat\":\"슬랭\",\"w\":\"I'm down\",\"m\":\"나 콜! 좋아, 할래\",\"lit\":\"\",\"ex\":\"Pizza tonight? I'm down!\",\"exko\":\"오늘 밤 피자? 콜!\",\"tip\":\"'기분이 다운됐다'가 아니라 '나 낄래!'라는 뜻. 우울할 땐 I'm feeling down이라고 해요.\"},{\"id\":\"hang-out\",\"r\":\"N\",\"cat\":\"구동사\",\"w\":\"hang out\",\"m\":\"(친구와) 놀다, 어울리다\",\"lit\":\"\",\"ex\":\"Do you want to hang out this weekend?\",\"exko\":\"이번 주말에 같이 놀래?\",\"tip\":\"어른이 친구랑 논다고 할 때 play를 쓰면 어색해요. 정답은 hang out!\"},{\"id\":\"whats-up\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"What's up?\",\"m\":\"잘 지내? 무슨 일이야?\",\"lit\":\"\",\"ex\":\"Hey, what's up? — Not much.\",\"exko\":\"야, 잘 지내? — 별일 없어.\",\"tip\":\"위를 묻는 게 아니에요! 대답은 Not much(별일 없어)가 국룰.\"},{\"id\":\"sounds-good\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Sounds good\",\"m\":\"좋아, 그렇게 하자\",\"lit\":\"\",\"ex\":\"Let's meet at six. — Sounds good!\",\"exko\":\"6시에 만나자. — 좋아!\",\"tip\":\"약속이나 제안에 OK할 때 쓰는 만능 대답. 문자로도 엄청 자주 써요.\"},{\"id\":\"no-way\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"No way!\",\"m\":\"말도 안 돼! 헐!\",\"lit\":\"\",\"ex\":\"No way! You won the lottery?\",\"exko\":\"헐! 너 복권 당첨됐어?\",\"tip\":\"놀랄 때는 '헐!', 거절할 때는 '절대 안 돼!'. 말투에 따라 뜻이 달라져요.\"},{\"id\":\"awesome\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Awesome!\",\"m\":\"최고야! 멋지다!\",\"lit\":\"\",\"ex\":\"You got the job? Awesome!\",\"exko\":\"너 취직했어? 대박!\",\"tip\":\"원래 '경외심을 불러일으키는'이라는 무거운 뜻이었는데, 지금은 미국인의 최애 리액션이에요.\"},{\"id\":\"same-here\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Same here\",\"m\":\"나도 그래\",\"lit\":\"\",\"ex\":\"I'm so tired. — Same here.\",\"exko\":\"나 너무 피곤해. — 나도.\",\"tip\":\"Me too와 비슷하지만 더 캐주얼해요. 일본어 だよね와 같은 공감 리액션.\"},{\"id\":\"you-bet\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"You bet\",\"m\":\"물론이지, 당연하지\",\"lit\":\"\",\"ex\":\"Can you help me? — You bet!\",\"exko\":\"도와줄 수 있어? — 당연하지!\",\"tip\":\"'내기해도 좋을 만큼 확실해'라는 데서 온 말. Thank you에 '천만에'로 답할 때도 써요.\"},{\"id\":\"take-care\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Take care\",\"m\":\"잘 지내, 몸조심해\",\"lit\":\"\",\"ex\":\"See you next week. Take care!\",\"exko\":\"다음 주에 봐. 잘 지내!\",\"tip\":\"헤어질 때 Bye 대신 쓰면 따뜻한 느낌이 나요. 메일 끝인사로도 좋아요.\"},{\"id\":\"see-you-later\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"See you later\",\"m\":\"나중에 봐\",\"lit\":\"\",\"ex\":\"I have to go now. See you later!\",\"exko\":\"이제 가 봐야 해. 나중에 봐!\",\"tip\":\"꼭 다시 만날 약속이 없어도 쓰는 작별 인사. 줄여서 See ya! 또는 Later!\"},{\"id\":\"long-time-no-see\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Long time no see\",\"m\":\"오랜만이야\",\"lit\":\"\",\"ex\":\"Wow, long time no see! How have you been?\",\"exko\":\"와, 오랜만이야! 어떻게 지냈어?\",\"tip\":\"문법적으로는 이상하지만 원어민도 쓰는 말. 중국어 '好久不见'을 그대로 옮긴 데서 왔다는 설이 있어요.\"},{\"id\":\"never-mind\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Never mind\",\"m\":\"아니야, 됐어 / 신경 쓰지 마\",\"lit\":\"\",\"ex\":\"Never mind, I found my keys.\",\"exko\":\"아냐 됐어, 열쇠 찾았어.\",\"tip\":\"하던 말을 '아냐, 됐어' 하고 취소할 때 딱이에요. 신경 쓰지 말라는 뜻으로도 써요.\"},{\"id\":\"hold-on\",\"r\":\"N\",\"cat\":\"구동사\",\"w\":\"hold on\",\"m\":\"잠깐만 (기다려)\",\"lit\":\"\",\"ex\":\"Hold on, let me check my calendar.\",\"exko\":\"잠깐만, 일정 좀 확인해 볼게.\",\"tip\":\"전화에서 Hold on a sec! 하면 '잠시만요'. Wait보다 부드러운 느낌이에요.\"},{\"id\":\"figure-out\",\"r\":\"N\",\"cat\":\"구동사\",\"w\":\"figure out\",\"m\":\"알아내다, 해결하다\",\"lit\":\"\",\"ex\":\"I can't figure out this math problem.\",\"exko\":\"이 수학 문제를 못 풀겠어.\",\"tip\":\"머리를 굴려서 답을 '알아낼' 때 원어민이 정말 자주 쓰는 구동사예요.\"},{\"id\":\"come-on\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Come on!\",\"m\":\"힘내! / 에이~ / 빨리!\",\"lit\":\"\",\"ex\":\"Come on, you can do it!\",\"exko\":\"힘내, 넌 할 수 있어!\",\"tip\":\"말투에 따라 '힘내!', '에이, 설마', '빨리 좀!'으로 뜻이 확 바뀌는 카멜레온 표현이에요.\"},{\"id\":\"im-starving\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"I'm starving\",\"m\":\"배고파 죽겠어\",\"lit\":\"\",\"ex\":\"Let's eat. I'm starving!\",\"exko\":\"밥 먹자. 배고파 죽겠어!\",\"tip\":\"원래 '굶주리다'라는 뜻인데 일상에서는 과장해서 써요. 일본어 お腹ぺこぺこ와 같은 느낌!\"},{\"id\":\"good-for-you\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Good for you!\",\"m\":\"잘됐다! 잘했어!\",\"lit\":\"\",\"ex\":\"You passed the test? Good for you!\",\"exko\":\"시험 붙었어? 잘됐다!\",\"tip\":\"좋은 소식을 축하할 때 써요. 비꼬는 말투로 하면 '어쩌라고'가 되니 밝게 말하세요!\"},{\"id\":\"fair-enough\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Fair enough\",\"m\":\"그럴 만하네, 일리 있어\",\"lit\":\"\",\"ex\":\"I'm too tired to go out. — Fair enough.\",\"exko\":\"너무 피곤해서 못 나가겠어. — 그럴 만하지.\",\"tip\":\"상대의 이유를 납득하고 쿨하게 인정할 때 쓰는 대답이에요.\"},{\"id\":\"get-up\",\"r\":\"N\",\"cat\":\"구동사\",\"w\":\"get up\",\"m\":\"(잠자리에서) 일어나다\",\"lit\":\"\",\"ex\":\"I get up at seven every day.\",\"exko\":\"나는 매일 7시에 일어나.\",\"tip\":\"wake up은 '잠에서 깨다', get up은 '몸을 일으키다'. 깨고 나서 못 일어날 때도 있죠!\"},{\"id\":\"calm-down\",\"r\":\"N\",\"cat\":\"구동사\",\"w\":\"calm down\",\"m\":\"진정하다\",\"lit\":\"\",\"ex\":\"Calm down. Everything will be okay.\",\"exko\":\"진정해. 다 괜찮을 거야.\",\"tip\":\"화난 사람에게 그냥 Calm down!이라고만 하면 오히려 더 화나게 할 수 있으니 조심!\"},{\"id\":\"oh-my-gosh\",\"r\":\"N\",\"cat\":\"리액션\",\"w\":\"Oh my gosh!\",\"m\":\"세상에! 어머나!\",\"lit\":\"\",\"ex\":\"Oh my gosh, this is so cute!\",\"exko\":\"세상에, 이거 너무 귀여워!\",\"tip\":\"Oh my God을 부드럽게 바꾼 말. 문자로는 OMG!\"},{\"id\":\"cheers\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Cheers!\",\"m\":\"건배! / 고마워 (영국)\",\"lit\":\"\",\"ex\":\"Let's make a toast. Cheers!\",\"exko\":\"건배하자. 건배!\",\"tip\":\"영국에서는 '고마워', '잘 가'라는 뜻으로도 엄청 자주 써요.\"},{\"id\":\"hows-it-going\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"How's it going?\",\"m\":\"어떻게 지내? 잘 돼 가?\",\"lit\":\"\",\"ex\":\"Hi, Jake! How's it going? — Pretty good!\",\"exko\":\"안녕, 제이크! 잘 지내? — 꽤 좋아!\",\"tip\":\"How are you?보다 캐주얼한 인사. 근황을 길게 말할 필요 없이 Good!이면 충분해요.\"},{\"id\":\"piece-of-cake\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"piece of cake\",\"m\":\"식은 죽 먹기\",\"lit\":\"케이크 한 조각\",\"ex\":\"The test was a piece of cake.\",\"exko\":\"시험은 식은 죽 먹기였어.\",\"tip\":\"케이크 한 조각 먹는 것만큼 쉽다는 뜻. 일본어 朝飯前와 같아요.\"},{\"id\":\"spill-the-tea\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"spill the tea\",\"m\":\"(소문·가십을) 털어놓다\",\"lit\":\"\",\"ex\":\"Come on, spill the tea! What happened last night?\",\"exko\":\"얼른 썰 풀어 봐! 어젯밤에 무슨 일 있었어?\",\"tip\":\"직역은 '차를 쏟다'. tea가 T(truth, 진실)에서 왔다는 설이 있어요. 한국어 '썰 풀어 봐'와 비슷!\"},{\"id\":\"no-cap\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"No cap\",\"m\":\"진짜로, 뻥 아니고\",\"lit\":\"\",\"ex\":\"This is the best burger ever, no cap.\",\"exko\":\"이거 진짜 인생 버거야, 뻥 아님.\",\"tip\":\"cap은 슬랭으로 '거짓말'. 그래서 No cap은 '리얼', '실화임'이라는 뜻이에요.\"},{\"id\":\"lowkey\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"lowkey\",\"m\":\"은근히, 살짝\",\"lit\":\"\",\"ex\":\"I lowkey want to go home now.\",\"exko\":\"나 은근 지금 집에 가고 싶어.\",\"tip\":\"반대말 highkey는 '대놓고, 엄청'. 속마음을 살짝 털어놓을 때 써요.\"},{\"id\":\"good-vibes\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"good vibes\",\"m\":\"좋은 분위기, 좋은 느낌\",\"lit\":\"\",\"ex\":\"This café has really good vibes.\",\"exko\":\"이 카페 분위기 진짜 좋다.\",\"tip\":\"vibe는 vibration(진동)에서 온 말로, 사람이나 장소에서 느껴지는 분위기를 말해요.\"},{\"id\":\"goat\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"GOAT\",\"m\":\"역대 최고\",\"lit\":\"\",\"ex\":\"My mom's kimchi stew is the GOAT.\",\"exko\":\"우리 엄마 김치찌개가 역대 최고야.\",\"tip\":\"Greatest Of All Time의 줄임말. 염소(goat)라고 놀리는 게 아니라 최고의 칭찬이에요!\"},{\"id\":\"hit-the-books\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"hit the books\",\"m\":\"열심히 공부하다\",\"lit\":\"책을 치다\",\"ex\":\"I have an exam tomorrow, so I need to hit the books.\",\"exko\":\"내일 시험이라 공부 열심히 해야 해.\",\"tip\":\"책을 때리는 게 아니라 책에 '달려든다'는 느낌. 시험 기간 필수 표현!\"},{\"id\":\"hit-the-sack\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"hit the sack\",\"m\":\"잠자리에 들다\",\"lit\":\"자루를 치다\",\"ex\":\"I'm exhausted. I'm going to hit the sack.\",\"exko\":\"완전 지쳤어. 이제 자러 갈래.\",\"tip\":\"옛날에 짚을 채운 자루(sack)를 침대로 썼던 데서 온 말. hit the hay도 같은 뜻이에요.\"},{\"id\":\"call-it-a-day\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"call it a day\",\"m\":\"오늘은 여기까지 하다\",\"lit\":\"그것을 하루라고 부르다\",\"ex\":\"It's late. Let's call it a day.\",\"exko\":\"늦었다. 오늘은 여기까지 하자.\",\"tip\":\"일이나 공부를 마무리할 때 쓰는 단골 표현. 일본어 お疲れ様です가 생각나는 순간!\"},{\"id\":\"on-the-same-page\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"on the same page\",\"m\":\"같은 생각이다, 이해가 일치하다\",\"lit\":\"같은 페이지에 있다\",\"ex\":\"Let's make sure we're on the same page.\",\"exko\":\"우리 생각이 같은지 확인하자.\",\"tip\":\"모두 같은 페이지를 펴야 수업이 되듯, 서로 이해가 맞는다는 뜻이에요.\"},{\"id\":\"under-the-weather\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"under the weather\",\"m\":\"몸이 좀 안 좋은\",\"lit\":\"날씨 아래에 있는\",\"ex\":\"I'm feeling a bit under the weather today.\",\"exko\":\"오늘 몸이 좀 안 좋아.\",\"tip\":\"궂은 날씨에 뱃멀미하는 선원을 갑판 아래로 내려보내던 데서 왔다는 설. sick보다 부드러운 표현이에요.\"},{\"id\":\"give-it-a-shot\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"give it a shot\",\"m\":\"한번 해 보다\",\"lit\":\"한 발 쏴 보다\",\"ex\":\"I've never tried surfing, but I'll give it a shot.\",\"exko\":\"서핑은 해 본 적 없지만 한번 해 볼게.\",\"tip\":\"결과는 몰라도 '일단 도전!' 하는 느낌. give it a try와 같은 뜻이에요.\"},{\"id\":\"run-out-of\",\"r\":\"R\",\"cat\":\"구동사\",\"w\":\"run out of\",\"m\":\"~이 다 떨어지다\",\"lit\":\"\",\"ex\":\"We ran out of milk.\",\"exko\":\"우유가 다 떨어졌어.\",\"tip\":\"물건, 시간, 인내심까지 '바닥났을' 때 다 쓸 수 있어요.\"},{\"id\":\"look-forward-to\",\"r\":\"R\",\"cat\":\"구동사\",\"w\":\"look forward to\",\"m\":\"~을 기대하다, 고대하다\",\"lit\":\"\",\"ex\":\"I'm looking forward to the trip.\",\"exko\":\"여행이 너무 기대돼.\",\"tip\":\"to 뒤에는 동사원형이 아니라 명사나 -ing가 와요. I look forward to seeing you!\"},{\"id\":\"put-off\",\"r\":\"R\",\"cat\":\"구동사\",\"w\":\"put off\",\"m\":\"미루다\",\"lit\":\"\",\"ex\":\"Stop putting off your homework!\",\"exko\":\"숙제 좀 그만 미뤄!\",\"tip\":\"해야 할 일을 자꾸 미루는 버릇은 만국 공통이죠. 오늘 목표는 put off 금지!\"},{\"id\":\"tell-me-about-it\",\"r\":\"R\",\"cat\":\"리액션\",\"w\":\"Tell me about it\",\"m\":\"내 말이, 그러니까\",\"lit\":\"\",\"ex\":\"This weather is so hot! — Tell me about it.\",\"exko\":\"날씨 너무 덥다! — 내 말이.\",\"tip\":\"'그것에 대해 말해 줘'가 아니라 '완전 공감!'이라는 뜻일 때가 많아요. 말투가 힌트!\"},{\"id\":\"i-feel-you\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"I feel you\",\"m\":\"무슨 마음인지 알아\",\"lit\":\"\",\"ex\":\"Mondays are the worst. — I feel you.\",\"exko\":\"월요일은 최악이야. — 그 맘 알지.\",\"tip\":\"상대의 감정에 깊이 공감할 때 쓰는 캐주얼한 말. 일본어 わかる!와 같은 느낌이에요.\"},{\"id\":\"couch-potato\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"couch potato\",\"m\":\"소파에서 뒹굴며 TV만 보는 사람\",\"lit\":\"소파 위 감자\",\"ex\":\"On weekends, I'm a total couch potato.\",\"exko\":\"주말엔 나 완전 소파와 한 몸이야.\",\"tip\":\"소파에 감자처럼 붙어서 꼼짝 않는 모습. 일본어 ゴロゴロ하는 사람이 바로 이거예요!\"},{\"id\":\"ghost\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"ghost\",\"m\":\"잠수 타다, 갑자기 연락을 끊다\",\"lit\":\"\",\"ex\":\"He ghosted me after our first date.\",\"exko\":\"걔가 첫 데이트 후에 잠수 탔어.\",\"tip\":\"유령처럼 갑자기 사라진다는 뜻. 한국어 '잠수 타다'와 딱 맞아요.\"},{\"id\":\"fomo\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"FOMO\",\"m\":\"나만 놓칠까 봐 불안한 마음\",\"lit\":\"\",\"ex\":\"I bought the concert ticket because of FOMO.\",\"exko\":\"나만 못 갈까 봐 불안해서 콘서트 표를 샀어.\",\"tip\":\"Fear Of Missing Out의 줄임말. 남들 다 하는 걸 나만 놓칠까 봐 조급해지는 마음이에요.\"},{\"id\":\"break-a-leg\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"break a leg\",\"m\":\"행운을 빌어 (공연·발표 전에)\",\"lit\":\"다리를 부러뜨려라\",\"ex\":\"Your audition is today? Break a leg!\",\"exko\":\"오늘 오디션이야? 잘하고 와!\",\"tip\":\"무대에서 Good luck이라고 하면 오히려 불운이 온다는 미신 때문에 반대로 말하게 됐다는 설이 있어요.\"},{\"id\":\"raining-cats-and-dogs\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"It's raining cats and dogs\",\"m\":\"비가 억수같이 쏟아진다\",\"lit\":\"고양이와 개가 비처럼 내린다\",\"ex\":\"Take an umbrella. It's raining cats and dogs!\",\"exko\":\"우산 챙겨. 비가 엄청 쏟아져!\",\"tip\":\"유래는 여러 설이 있지만 확실하지 않아요. 요즘 원어민은 It's pouring!도 많이 써요.\"},{\"id\":\"ball-in-your-court\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"The ball is in your court\",\"m\":\"이제 네가 결정할 차례야\",\"lit\":\"공이 네 코트에 있다\",\"ex\":\"I've made my offer. The ball is in your court.\",\"exko\":\"난 제안했어. 이제 네가 결정할 차례야.\",\"tip\":\"테니스에서 공이 상대 코트로 넘어가면 그쪽이 쳐야 하죠. 결정권을 넘길 때 쓰는 말이에요.\"},{\"id\":\"cat-out-of-the-bag\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"let the cat out of the bag\",\"m\":\"비밀을 무심코 누설하다\",\"lit\":\"고양이를 자루에서 꺼내다\",\"ex\":\"Who let the cat out of the bag about the surprise party?\",\"exko\":\"깜짝 파티 비밀을 누가 말해 버렸어?\",\"tip\":\"자루에 든 새끼 돼지라고 속이고 고양이를 팔던 사기가 들통난 데서 왔다는 설. 일본어 口が滑る와 비슷해요.\"},{\"id\":\"once-in-a-blue-moon\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"once in a blue moon\",\"m\":\"아주 가끔\",\"lit\":\"블루문이 뜰 때 한 번\",\"ex\":\"I only eat fast food once in a blue moon.\",\"exko\":\"패스트푸드는 아주 가끔만 먹어.\",\"tip\":\"블루문은 한 달에 보름달이 두 번 뜰 때의 두 번째 보름달. 그만큼 드물다는 뜻이에요!\"},{\"id\":\"bite-the-bullet\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"bite the bullet\",\"m\":\"이를 악물고 (싫은 일을) 하다\",\"lit\":\"총알을 깨물다\",\"ex\":\"I hate going to the dentist, but I'll bite the bullet.\",\"exko\":\"치과 가기 싫지만 꾹 참고 갈게.\",\"tip\":\"마취제가 없던 시절 수술할 때 총알을 물고 고통을 참았다는 데서 유래했다는 설이 있어요.\"},{\"id\":\"cost-an-arm-and-a-leg\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"cost an arm and a leg\",\"m\":\"엄청 비싸다\",\"lit\":\"팔 하나와 다리 하나 값이 들다\",\"ex\":\"This bag cost an arm and a leg.\",\"exko\":\"이 가방 진짜 비쌌어.\",\"tip\":\"팔다리를 내줘야 할 만큼 비싸다는 과장 표현. 한국어 '눈알이 튀어나오게 비싸다'와 비슷해요.\"},{\"id\":\"hit-the-nail-on-the-head\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"hit the nail on the head\",\"m\":\"정곡을 찌르다\",\"lit\":\"못의 머리를 정확히 치다\",\"ex\":\"You hit the nail on the head. That's exactly the problem.\",\"exko\":\"정곡을 찔렀어. 그게 바로 문제야.\",\"tip\":\"망치로 못 머리를 딱 맞히듯 핵심을 정확히 짚었다는 뜻이에요.\"},{\"id\":\"elephant-in-the-room\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"the elephant in the room\",\"m\":\"모두 알지만 아무도 말하지 않는 문제\",\"lit\":\"방 안의 코끼리\",\"ex\":\"Let's talk about the elephant in the room.\",\"exko\":\"다들 알면서 모른 척하는 그 문제 얘기 좀 하자.\",\"tip\":\"방에 거대한 코끼리가 있는데 다들 못 본 척하는 어색한 장면을 떠올려 보세요.\"},{\"id\":\"blessing-in-disguise\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"a blessing in disguise\",\"m\":\"전화위복\",\"lit\":\"변장한 축복\",\"ex\":\"Losing that job was a blessing in disguise.\",\"exko\":\"그 일자리를 잃은 게 오히려 전화위복이었어.\",\"tip\":\"처음엔 나쁜 일 같았는데 알고 보니 축복이었다는 뜻. 한국어 '전화위복'과 딱 맞아요.\"},{\"id\":\"break-the-ice\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"break the ice\",\"m\":\"어색한 분위기를 깨다\",\"lit\":\"얼음을 깨다\",\"ex\":\"He told a joke to break the ice.\",\"exko\":\"그는 어색함을 깨려고 농담을 했어.\",\"tip\":\"얼어붙은 물길의 얼음을 깨서 배가 지나갈 길을 내던 데서 온 말. '아이스브레이킹'도 여기서 나왔어요!\"},{\"id\":\"barking-up-the-wrong-tree\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"barking up the wrong tree\",\"m\":\"헛다리 짚다\",\"lit\":\"엉뚱한 나무를 보고 짖다\",\"ex\":\"If you think I ate your cake, you're barking up the wrong tree.\",\"exko\":\"내가 네 케이크 먹었다고 생각하면 헛다리 짚은 거야.\",\"tip\":\"사냥개가 사냥감이 없는 나무를 보고 계속 짖는 모습에서 나왔어요. 한국어 '헛다리 짚다'.\"},{\"id\":\"sleep-on-it\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"sleep on it\",\"m\":\"하룻밤 자면서 생각해 보다\",\"lit\":\"그 위에서 자다\",\"ex\":\"It's a big decision. Let me sleep on it.\",\"exko\":\"중요한 결정이니까 하룻밤 생각해 볼게.\",\"tip\":\"바로 대답하기 어려울 때 시간을 버는 세련된 표현이에요. 실제로 자고 나면 생각이 정리되기도 하죠.\"},{\"id\":\"beat-around-the-bush\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"beat around the bush\",\"m\":\"말을 빙빙 돌리다\",\"lit\":\"덤불 주변을 두드리다\",\"ex\":\"Stop beating around the bush and tell me the truth.\",\"exko\":\"말 돌리지 말고 사실대로 말해.\",\"tip\":\"사냥할 때 덤불 주변만 두드리며 새를 몰던 데서 온 말. 한국어 '변죽을 울리다'와 비슷해요.\"},{\"id\":\"butterflies-in-my-stomach\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"have butterflies in my stomach\",\"m\":\"(긴장·설렘으로) 가슴이 두근거리다\",\"lit\":\"배 속에 나비가 있다\",\"ex\":\"I have butterflies in my stomach before my speech.\",\"exko\":\"발표 전이라 너무 떨려.\",\"tip\":\"배 속에서 나비가 팔랑거리는 듯한 긴장감. 일본어 ドキドキ와 같은 느낌이에요!\"},{\"id\":\"when-in-rome\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"When in Rome, do as the Romans do\",\"m\":\"로마에 가면 로마법을 따르라\",\"lit\":\"로마에 있을 때는 로마 사람들처럼 하라\",\"ex\":\"In Japan, people take off their shoes inside. When in Rome, do as the Romans do!\",\"exko\":\"일본에서는 실내에서 신발을 벗어. 로마에 가면 로마법을 따라야지!\",\"tip\":\"한국어와 똑같은 속담! 앞부분만 When in Rome...이라고 말해도 다 알아들어요.\"},{\"id\":\"actions-speak-louder\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Actions speak louder than words\",\"m\":\"말보다 행동이 중요하다\",\"lit\":\"행동은 말보다 크게 말한다\",\"ex\":\"Don't just say sorry. Actions speak louder than words.\",\"exko\":\"미안하다는 말만 하지 마. 말보다 행동이야.\",\"tip\":\"백 번 말하는 것보다 한 번 보여 주는 게 낫다는 뜻. 한국어 '백문이 불여일견'과도 통해요.\"},{\"id\":\"dont-judge-a-book\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Don't judge a book by its cover\",\"m\":\"겉모습만 보고 판단하지 마라\",\"lit\":\"표지만 보고 책을 판단하지 마라\",\"ex\":\"He looks scary, but he's really kind. Don't judge a book by its cover.\",\"exko\":\"그는 무서워 보이지만 정말 친절해. 겉모습만 보고 판단하지 마.\",\"tip\":\"한국어 '뚝배기보다 장맛'과 통하는 말. 표지가 별로여도 내용은 최고일 수 있어요!\"},{\"id\":\"early-bird\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"The early bird catches the worm\",\"m\":\"일찍 일어나는 새가 벌레를 잡는다\",\"lit\":\"일찍 일어난 새가 벌레를 잡는다\",\"ex\":\"I got the last ticket at 7 a.m. The early bird catches the worm!\",\"exko\":\"아침 7시에 마지막 표를 샀어. 일찍 일어나는 새가 벌레를 잡지!\",\"tip\":\"아침형 인간은 early bird, 밤형 인간은 night owl(올빼미)이라고 불러요.\"},{\"id\":\"silver-lining\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Every cloud has a silver lining\",\"m\":\"나쁜 일에도 좋은 면은 있다\",\"lit\":\"모든 구름에는 은빛 테두리가 있다\",\"ex\":\"I missed the train, but every cloud has a silver lining. I found a great café.\",\"exko\":\"기차를 놓쳤지만 나쁜 일에도 좋은 면은 있지. 멋진 카페를 발견했어.\",\"tip\":\"먹구름 뒤에 해가 있어 가장자리가 은빛으로 빛나는 모습에서 온 말. 한국어 '쥐구멍에도 볕 들 날 있다'와 비슷해요.\"},{\"id\":\"curiosity-killed-the-cat\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Curiosity killed the cat\",\"m\":\"지나친 호기심은 화를 부른다\",\"lit\":\"호기심이 고양이를 죽였다\",\"ex\":\"Don't open that box. Curiosity killed the cat!\",\"exko\":\"그 상자 열지 마. 호기심이 화를 부른다고!\",\"tip\":\"목숨이 아홉 개라는 고양이도 호기심 때문에 당했다니! 너무 캐묻는 친구에게 장난스럽게 써요.\"},{\"id\":\"practice-makes-perfect\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Practice makes perfect\",\"m\":\"연습하면 완벽해진다\",\"lit\":\"연습이 완벽을 만든다\",\"ex\":\"Keep studying every day. Practice makes perfect!\",\"exko\":\"매일 꾸준히 공부해. 연습하면 완벽해져!\",\"tip\":\"매일 목표를 채우는 여러분을 위한 속담! 일본어 石の上にも三年과 함께 기억하세요.\"},{\"id\":\"apple-a-day\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"An apple a day keeps the doctor away\",\"m\":\"하루 사과 한 개면 의사가 필요 없다\",\"lit\":\"하루 사과 하나가 의사를 멀리한다\",\"ex\":\"Here, have an apple. An apple a day keeps the doctor away!\",\"exko\":\"자, 사과 먹어. 하루에 사과 하나면 병원 갈 일 없대!\",\"tip\":\"19세기 영국 웨일스 지방의 속담에서 왔어요. day와 away의 운율 덕분에 아이들도 다 외워요.\"}]");
const SEASON_CARDS_JA = [];
const SEASON_CARDS_EN = JSON.parse("[{\"id\":\"ny-happy-new-year\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Happy New Year!\",\"m\":\"새해 복 많이 받으세요!\",\"lit\":\"\",\"ex\":\"Happy New Year! Let's make it a great one.\",\"exko\":\"새해 복 많이 받아! 멋진 한 해 만들자.\",\"tip\":\"12월 31일 밤 카운트다운이 끝나는 순간 다 같이 외치는 말이기도 해요.\",\"season\":\"newyear\"},{\"id\":\"ny-resolution\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"New Year's resolution\",\"m\":\"새해 결심\",\"lit\":\"\",\"ex\":\"My New Year's resolution is to read more books.\",\"exko\":\"내 새해 결심은 책을 더 많이 읽는 거야.\",\"tip\":\"1월 중순쯤이면 '벌써 포기했어?'가 미국에서도 단골 농담. 작심삼일은 만국 공통!\",\"season\":\"newyear\"},{\"id\":\"ny-ring-in\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"ring in the new year\",\"m\":\"새해를 맞이하다 (축하하며)\",\"lit\":\"종을 울려 새해를 맞다\",\"ex\":\"We rang in the new year with fireworks.\",\"exko\":\"우리는 불꽃놀이로 새해를 맞이했어.\",\"tip\":\"뉴욕 타임스스퀘어에선 대형 크리스털 볼이 떨어지는 걸 보며 새해를 맞아요.\",\"season\":\"newyear\"},{\"id\":\"ny-new-leaf\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"turn over a new leaf\",\"m\":\"새사람이 되다, 마음을 고쳐먹다\",\"lit\":\"새 책장을 넘기다\",\"ex\":\"This year, I'm going to turn over a new leaf.\",\"exko\":\"올해는 새사람이 될 거야.\",\"tip\":\"여기서 leaf는 나뭇잎이 아니라 책의 '한 장'. 새 페이지를 펼친다는 이미지예요.\",\"season\":\"newyear\"},{\"id\":\"ny-out-with-old\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"Out with the old, in with the new\",\"m\":\"묵은 것은 보내고 새것을 맞이하자\",\"lit\":\"헌것은 밖으로, 새것은 안으로\",\"ex\":\"I threw away my old shoes. Out with the old, in with the new!\",\"exko\":\"헌 신발 버렸어. 묵은 건 보내고 새것을 맞이해야지!\",\"tip\":\"연말 정리나 새 출발 때 딱 맞는 말. 물건뿐 아니라 습관·마음가짐에도 써요.\",\"season\":\"newyear\"},{\"id\":\"ny-thousand-miles\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"A journey of a thousand miles begins with a single step\",\"m\":\"천 리 길도 한 걸음부터\",\"lit\":\"천 마일의 여행도 한 걸음에서 시작된다\",\"ex\":\"Just start today. A journey of a thousand miles begins with a single step.\",\"exko\":\"오늘 바로 시작해. 천 리 길도 한 걸음부터야.\",\"tip\":\"노자의 말에서 온 표현. 새해 목표를 세울 때 응원 문구로 인기예요.\",\"season\":\"newyear\"},{\"id\":\"sp-spring-cleaning\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"spring cleaning\",\"m\":\"봄맞이 대청소\",\"lit\":\"\",\"ex\":\"We do spring cleaning every March.\",\"exko\":\"우리는 매년 3월에 봄맞이 대청소를 해.\",\"tip\":\"일본은 연말 대청소, 미국은 봄 대청소! 컴퓨터 파일 정리에도 농담처럼 써요.\",\"season\":\"spring\"},{\"id\":\"sp-spring-break\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"spring break\",\"m\":\"봄방학\",\"lit\":\"\",\"ex\":\"What are you doing for spring break?\",\"exko\":\"봄방학에 뭐 해?\",\"tip\":\"미국 대학생들은 봄방학에 플로리다 해변으로 몰려가는 게 전통이에요.\",\"season\":\"spring\"},{\"id\":\"sp-spring-fever\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"spring fever\",\"m\":\"봄바람 (봄이라 들뜨는 마음)\",\"lit\":\"봄의 열병\",\"ex\":\"I can't focus. I've got spring fever.\",\"exko\":\"집중이 안 돼. 봄바람이 났나 봐.\",\"tip\":\"따뜻해지면 괜히 싱숭생숭한 그 기분. 진짜 병은 아니니 안심하세요.\",\"season\":\"spring\"},{\"id\":\"sp-full-bloom\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"in full bloom\",\"m\":\"꽃이 활짝 핀, 만개한\",\"lit\":\"\",\"ex\":\"The cherry blossoms are in full bloom.\",\"exko\":\"벚꽃이 활짝 폈어.\",\"tip\":\"워싱턴 D.C.에는 일본이 선물한 벚나무가 있어서 매년 봄 벚꽃 축제가 열려요.\",\"season\":\"spring\"},{\"id\":\"sp-spring-forward\",\"r\":\"SR\",\"cat\":\"생활 표현\",\"w\":\"spring forward\",\"m\":\"(서머타임으로) 시계를 한 시간 앞당기다\",\"lit\":\"봄에 앞으로 튀어 오르다\",\"ex\":\"Don't forget to spring forward this Sunday!\",\"exko\":\"이번 일요일에 시계 한 시간 앞당기는 거 잊지 마!\",\"tip\":\"Spring forward, fall back(봄엔 앞으로, 가을엔 뒤로)으로 서머타임을 외워요.\",\"season\":\"spring\"},{\"id\":\"sp-april-showers\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"April showers bring May flowers\",\"m\":\"고생 끝에 낙이 온다\",\"lit\":\"4월의 소나기가 5월의 꽃을 데려온다\",\"ex\":\"Hang in there. April showers bring May flowers.\",\"exko\":\"조금만 버텨. 고생 끝에 낙이 올 거야.\",\"tip\":\"힘든 시기가 지나면 좋은 일이 온다는 위로의 말. 비 오는 봄날 단골 문구예요.\",\"season\":\"spring\"},{\"id\":\"su-summer-vacation\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"summer vacation\",\"m\":\"여름 방학, 여름 휴가\",\"lit\":\"\",\"ex\":\"I'm going to the beach for summer vacation.\",\"exko\":\"여름 휴가 때 바닷가에 갈 거야.\",\"tip\":\"미국 학교의 여름 방학은 무려 2~3개월! 그래서 summer camp 문화가 발달했어요.\",\"season\":\"summer\"},{\"id\":\"su-cookout\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"cookout\",\"m\":\"야외 바비큐 파티\",\"lit\":\"\",\"ex\":\"We're having a cookout in the backyard this Saturday.\",\"exko\":\"이번 토요일에 뒷마당에서 바비큐 파티 해.\",\"tip\":\"7월 4일 독립기념일엔 햄버거·핫도그 굽는 cookout이 국룰이에요.\",\"season\":\"summer\"},{\"id\":\"su-beat-the-heat\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"beat the heat\",\"m\":\"더위를 식히다, 더위를 이기다\",\"lit\":\"더위를 때려눕히다\",\"ex\":\"Let's get some ice cream to beat the heat.\",\"exko\":\"더위 식히게 아이스크림 먹자.\",\"tip\":\"수영장, 에어컨, 아이스크림… 더위 탈출 방법을 말할 때 다 써요.\",\"season\":\"summer\"},{\"id\":\"su-scorching\",\"r\":\"R\",\"cat\":\"리액션\",\"w\":\"It's scorching!\",\"m\":\"완전 찜통이야! 타 죽겠어!\",\"lit\":\"타는 듯해!\",\"ex\":\"It's scorching out there! I need some water.\",\"exko\":\"밖에 완전 찜통이야! 물 좀 마셔야겠어.\",\"tip\":\"hot보다 훨씬 센 표현. 덥다 못해 '지글지글 탈 것 같다'는 느낌이에요.\",\"season\":\"summer\"},{\"id\":\"su-dog-days\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"the dog days of summer\",\"m\":\"한여름 무더위, 삼복더위\",\"lit\":\"여름의 개의 날들\",\"ex\":\"We stayed inside during the dog days of summer.\",\"exko\":\"한여름 무더위 동안 우리는 집에만 있었어.\",\"tip\":\"개가 아니라 '큰개자리' 시리우스 별에서 유래! 한국 '복날'과 시기가 비슷해요.\",\"season\":\"summer\"},{\"id\":\"su-make-hay\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"Make hay while the sun shines\",\"m\":\"기회가 있을 때 잡아라\",\"lit\":\"해가 날 때 건초를 말려라\",\"ex\":\"The shop is busy now, so make hay while the sun shines.\",\"exko\":\"지금 가게가 잘되니까 기회 있을 때 바짝 벌어 둬.\",\"tip\":\"비 오면 건초를 못 말리던 농부들의 지혜. 한국어 '물 들어올 때 노 저어라'와 같아요.\",\"season\":\"summer\"},{\"id\":\"hw-trick-or-treat\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Trick or treat!\",\"m\":\"과자 안 주면 장난칠 거야!\",\"lit\":\"장난이냐 대접이냐\",\"ex\":\"Trick or treat! Can I have some candy?\",\"exko\":\"트릭 오어 트릿! 사탕 주세요!\",\"tip\":\"아이들이 분장하고 이웃집 문을 두드리며 외치는 말. 호박 바구니에 사탕을 받아 가요.\",\"season\":\"halloween\"},{\"id\":\"hw-costume-party\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"costume party\",\"m\":\"분장 파티, 코스튬 파티\",\"lit\":\"\",\"ex\":\"What are you wearing to the costume party?\",\"exko\":\"코스튬 파티에 뭐 입고 갈 거야?\",\"tip\":\"미국에선 어른들도 회사에서 할로윈 코스튬 대회를 열 만큼 진심이에요.\",\"season\":\"halloween\"},{\"id\":\"hw-spooky\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"spooky\",\"m\":\"으스스한, 오싹한\",\"lit\":\"\",\"ex\":\"This old house looks so spooky at night.\",\"exko\":\"이 오래된 집 밤에 보니까 너무 으스스하다.\",\"tip\":\"scary보다 귀엽고 가벼운 느낌. 10월은 아예 spooky season이라고 불러요.\",\"season\":\"halloween\"},{\"id\":\"hw-jack-o-lantern\",\"r\":\"R\",\"cat\":\"생활 표현\",\"w\":\"jack-o'-lantern\",\"m\":\"잭오랜턴 (호박 등불)\",\"lit\":\"등불 든 잭\",\"ex\":\"We carved a jack-o'-lantern with a big smile.\",\"exko\":\"크게 웃는 얼굴로 호박 등을 조각했어.\",\"tip\":\"원래 아일랜드에선 순무로 만들었는데, 미국에 와서 호박으로 바뀌었대요.\",\"season\":\"halloween\"},{\"id\":\"hw-skeleton-closet\",\"r\":\"SR\",\"cat\":\"관용구\",\"w\":\"skeleton in the closet\",\"m\":\"감추고 싶은 비밀, 숨겨진 과거\",\"lit\":\"옷장 속 해골\",\"ex\":\"Everyone has a skeleton in the closet.\",\"exko\":\"누구나 숨기고 싶은 비밀 하나쯤은 있어.\",\"tip\":\"옷장에 해골을 숨겨 둔 것처럼 남이 알면 곤란한 비밀. 할로윈에 딱 어울리죠?\",\"season\":\"halloween\"},{\"id\":\"hw-speak-of-devil\",\"r\":\"SSR\",\"cat\":\"관용구\",\"w\":\"Speak of the devil\",\"m\":\"호랑이도 제 말 하면 온다\",\"lit\":\"악마 얘기를 하면 (악마가 나타난다)\",\"ex\":\"Speak of the devil! We were just talking about you.\",\"exko\":\"호랑이도 제 말 하면 온다더니! 마침 네 얘기 하던 중이었어.\",\"tip\":\"한국은 호랑이, 영어는 악마! 뒷말은 생략하고 앞부분만 말하는 게 보통이에요.\",\"season\":\"halloween\"},{\"id\":\"au-thanksgiving\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Thanksgiving\",\"m\":\"추수감사절\",\"lit\":\"감사를 드림\",\"ex\":\"We eat turkey with my family on Thanksgiving.\",\"exko\":\"추수감사절에는 가족이랑 칠면조를 먹어.\",\"tip\":\"미국은 11월 넷째 목요일. 한국 추석처럼 온 가족이 모이는 큰 명절이에요.\",\"season\":\"autumn\"},{\"id\":\"au-fall-foliage\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"fall foliage\",\"m\":\"가을 단풍\",\"lit\":\"가을의 나뭇잎\",\"ex\":\"Let's drive up north to see the fall foliage.\",\"exko\":\"단풍 보러 북쪽으로 드라이브 가자.\",\"tip\":\"미국 뉴잉글랜드 지방은 단풍 명소! 단풍 구경꾼을 leaf peeper라고 불러요.\",\"season\":\"autumn\"},{\"id\":\"au-pumpkin-spice\",\"r\":\"R\",\"cat\":\"슬랭\",\"w\":\"pumpkin spice\",\"m\":\"펌킨 스파이스 (가을 한정 맛)\",\"lit\":\"호박 향신료\",\"ex\":\"Fall is here! Time for a pumpkin spice latte.\",\"exko\":\"가을이 왔다! 펌킨 스파이스 라테 마실 시간이야.\",\"tip\":\"가을만 되면 커피, 과자, 양초까지 전부 이 맛. 줄여서 PSL이라고 해요.\",\"season\":\"autumn\"},{\"id\":\"au-give-thanks\",\"r\":\"R\",\"cat\":\"생활 표현\",\"w\":\"give thanks\",\"m\":\"감사를 드리다\",\"lit\":\"\",\"ex\":\"Let's give thanks for this wonderful meal.\",\"exko\":\"이 멋진 식사에 감사드립시다.\",\"tip\":\"추수감사절 식사 전, 돌아가며 감사한 일을 하나씩 말하는 집이 많아요.\",\"season\":\"autumn\"},{\"id\":\"au-food-coma\",\"r\":\"SR\",\"cat\":\"슬랭\",\"w\":\"food coma\",\"m\":\"과식 후 식곤증\",\"lit\":\"음식 혼수상태\",\"ex\":\"I ate too much turkey. I'm in a food coma.\",\"exko\":\"칠면조를 너무 많이 먹었어. 배불러서 졸려 죽겠어.\",\"tip\":\"추수감사절 다음엔 소파에서 꾸벅꾸벅 food coma가 국룰. 한국의 '식곤증'이에요.\",\"season\":\"autumn\"},{\"id\":\"au-reap-sow\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"You reap what you sow\",\"m\":\"뿌린 대로 거둔다\",\"lit\":\"뿌린 것을 거둔다\",\"ex\":\"He studied hard all year. You reap what you sow.\",\"exko\":\"그는 일 년 내내 열심히 공부했어. 뿌린 대로 거두는 법이지.\",\"tip\":\"수확의 계절에 딱 맞는 속담. 좋은 결과에도 나쁜 결과에도 다 써요.\",\"season\":\"autumn\"},{\"id\":\"xm-merry-christmas\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Merry Christmas!\",\"m\":\"메리 크리스마스!\",\"lit\":\"즐거운 크리스마스\",\"ex\":\"Merry Christmas! I hope you like your present.\",\"exko\":\"메리 크리스마스! 선물 마음에 들면 좋겠다.\",\"tip\":\"영국에선 Happy Christmas라고도 해요. 줄여서 Merry Xmas!\",\"season\":\"christmas\"},{\"id\":\"xm-happy-holidays\",\"r\":\"N\",\"cat\":\"생활 표현\",\"w\":\"Happy holidays!\",\"m\":\"즐거운 연휴 보내세요!\",\"lit\":\"\",\"ex\":\"Happy holidays! See you next year.\",\"exko\":\"즐거운 연휴 보내! 내년에 봐.\",\"tip\":\"종교와 상관없이 쓸 수 있어서 미국 가게·회사에서 많이 써요.\",\"season\":\"christmas\"},{\"id\":\"xm-secret-santa\",\"r\":\"R\",\"cat\":\"생활 표현\",\"w\":\"Secret Santa\",\"m\":\"마니또 선물 교환\",\"lit\":\"비밀 산타\",\"ex\":\"I got a funny mug from my Secret Santa.\",\"exko\":\"마니또한테 웃긴 머그컵 받았어.\",\"tip\":\"제비뽑기로 정한 사람에게 몰래 선물하는 게임. 회사 송년 행사 단골이에요.\",\"season\":\"christmas\"},{\"id\":\"xm-deck-halls\",\"r\":\"R\",\"cat\":\"관용구\",\"w\":\"deck the halls\",\"m\":\"(크리스마스) 장식을 하다\",\"lit\":\"홀을 장식하다\",\"ex\":\"It's December! Time to deck the halls.\",\"exko\":\"12월이다! 크리스마스 장식할 시간이야.\",\"tip\":\"캐럴 'Deck the Halls'에서 온 말. 파라라라라~ 라라라라~\",\"season\":\"christmas\"},{\"id\":\"xm-stocking-stuffer\",\"r\":\"SR\",\"cat\":\"생활 표현\",\"w\":\"stocking stuffer\",\"m\":\"양말 속 작은 선물\",\"lit\":\"양말 채우기\",\"ex\":\"Candy and socks make great stocking stuffers.\",\"exko\":\"사탕이랑 양말은 양말 선물로 딱이야.\",\"tip\":\"벽난로에 건 큰 양말에 넣는 소소한 선물. 비싸지 않은 선물이라는 뜻으로도 써요.\",\"season\":\"christmas\"},{\"id\":\"xm-thought-counts\",\"r\":\"SSR\",\"cat\":\"속담\",\"w\":\"It's the thought that counts\",\"m\":\"중요한 건 마음이야\",\"lit\":\"중요한 것은 생각(마음)이다\",\"ex\":\"It's not expensive, but it's the thought that counts.\",\"exko\":\"비싼 건 아니지만 중요한 건 마음이잖아.\",\"tip\":\"선물이 좀 아쉬워도 웃으며 하는 말. 받는 쪽도 주는 쪽도 쓸 수 있어요.\",\"season\":\"christmas\"}]");
